<?php
require_once __DIR__.'/includes/bootstrap.php'; require_auth(); if(role()!=='admin'){http_response_code(403);exit('Accès réservé à l’administrateur.');}
$page_title='Fournisseurs';$pdo=db();
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();try{$n=trim($_POST['nom']??'');if($n==='')throw new Exception('Le nom du fournisseur est obligatoire.');$s=$pdo->prepare('INSERT INTO fournisseurs(nom,telephone,adresse,email) VALUES(?,?,?,?)');$s->execute([$n,trim($_POST['telephone']??''),trim($_POST['adresse']??''),trim($_POST['email']??'')?:null]);flash('Fournisseur ajouté.');}catch(Throwable $e){flash($e->getMessage(),'error');}redirect('suppliers.php');}
$rows=$pdo->query('SELECT f.*, COUNT(DISTINCT b.id) AS nb_achats, (SELECT solde_du FROM vue_fournisseurs_solde WHERE id = f.id) AS solde_du FROM fournisseurs f LEFT JOIN bons_achat b ON b.fournisseur_id = f.id GROUP BY f.id ORDER BY f.nom')->fetchAll();require 'includes/header.php';?>
<div class="panel"><h2>Ajouter un fournisseur</h2><form method="post" class="form-grid"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><div class="field"><label>Nom / raison sociale</label><input name="nom" required></div><div class="field"><label>Téléphone</label><input name="telephone" placeholder="6XXXXXXXX"></div><div class="field"><label>Adresse</label><input name="adresse"></div><div class="field"><label>E-mail</label><input type="email" name="email"></div><div class="field full"><button class="btn">Ajouter le fournisseur</button></div></form></div>
<div class="panel"><h2>Répertoire fournisseurs</h2><div class="table-wrap"><table><thead><tr><th>Fournisseur</th><th>Téléphone</th><th>Adresse</th><th>E-mail</th><th>Bons d'achat</th><th>Solde dû</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><b><?=e($r['nom'])?></b></td><td><?=e($r['telephone'])?></td><td><?=e($r['adresse'])?></td><td><?=e($r['email'])?></td><td><?=e($r['nb_achats'])?></td><td><?=money($r['solde_du'])?></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="6" class="empty">Aucun fournisseur.</td></tr><?php endif;?></tbody></table></div></div><?php require 'includes/footer.php';?>